package com.jnapanam.sportszone.notification.provider;
import com.jnapanam.sportszone.notification.model.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.mail.SimpleMailMessage;import org.springframework.mail.javamail.JavaMailSender;import org.springframework.stereotype.Component;
@Component public class SmtpEmailNotificationProvider implements NotificationProvider{private final JavaMailSender mail;private final String from;public SmtpEmailNotificationProvider(JavaMailSender mail,@Value("${app.notification.email.from:}")String from){this.mail=mail;this.from=from;}public NotificationChannel channel(){return NotificationChannel.EMAIL;}public String name(){return "smtp";}public String send(Notification n){String to=n.getUser().getEmail();if(to==null||to.isBlank())throw new IllegalStateException("User email is missing");SimpleMailMessage m=new SimpleMailMessage();if(from!=null&&!from.isBlank())m.setFrom(from);m.setTo(to);m.setSubject(n.getSubject()==null?"Jnapanam Sports Zone":n.getSubject());m.setText(n.getMessage());mail.send(m);return "smtp-"+n.getId();}}
